#!/usr/bin/env python3
"""SQL Тренажёр — единый самодостаточный файл.

Запуск:  python3 sql-trainer.py
Открыть: http://localhost:12000

Зависимости: только стандартная библиотека Python 3.8+.
Сгенерировано build_single.py — правки вносите в исходники многофайловой версии.
"""
import json
import sqlite3
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse

# ----- данные учебной базы (схлопотано из seed.py) -----
SCHEMA = '\nCREATE TABLE departments (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  budget REAL NOT NULL\n);\n\nCREATE TABLE employees (\n  id INTEGER PRIMARY KEY,\n  first_name TEXT NOT NULL,\n  last_name TEXT NOT NULL,\n  email TEXT NOT NULL,\n  department_id INTEGER REFERENCES departments(id),\n  salary REAL NOT NULL,\n  hired_at TEXT NOT NULL,\n  is_active INTEGER NOT NULL DEFAULT 1\n);\n\nCREATE TABLE projects (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL,\n  department_id INTEGER REFERENCES departments(id),\n  started_at TEXT NOT NULL,\n  finished_at TEXT\n);\n\nCREATE TABLE assignments (\n  id INTEGER PRIMARY KEY,\n  employee_id INTEGER REFERENCES employees(id),\n  project_id INTEGER REFERENCES projects(id),\n  role TEXT NOT NULL,\n  hours INTEGER NOT NULL\n);\n'
DEPARTMENTS = [(1, 'Engineering', 1200000), (2, 'Sales', 600000), (3, 'Marketing', 450000), (4, 'Support', 300000), (5, 'Finance', 500000)]
EMPLOYEES = [(1, 'Ivan', 'Petrov', 'ivan.petrov@corp.ru', 1, 180000, '2019-03-11', 1), (2, 'Maria', 'Ivanova', 'maria.ivanova@corp.ru', 1, 165000, '2020-07-01', 1), (3, 'Alexey', 'Smirnov', 'alexey.smirnov@corp.ru', 1, 210000, '2017-01-20', 1), (4, 'Olga', 'Kuznetsova', 'olga.kuznetsova@corp.ru', 2, 120000, '2021-02-15', 1), (5, 'Dmitry', 'Volkov', 'dmitry.volkov@corp.ru', 2, 135000, '2018-09-03', 1), (6, 'Anna', 'Sokolova', 'anna.sokolova@corp.ru', 3, 110000, '2022-05-30', 1), (7, 'Sergey', 'Popov', 'sergey.popov@corp.ru', 3, 95000, '2023-01-09', 1), (8, 'Ekaterina', 'Lebedeva', 'ekaterina.lebedeva@corp.ru', 4, 88000, '2021-11-22', 1), (9, 'Nikolai', 'Kozlov', 'nikolai.kozlov@corp.ru', 4, 92000, '2019-06-17', 0), (10, 'Tatiana', 'Novikova', 'tatiana.novikova@corp.ru', 5, 150000, '2016-04-05', 1), (11, 'Pavel', 'Morozov', 'pavel.morozov@corp.ru', 5, 142000, '2020-10-12', 1), (12, 'Elena', 'Vasileva', 'elena.vasileva@corp.ru', 1, 195000, '2018-12-01', 0), (13, 'Andrey', 'Zaitsev', 'andrey.zaitsev@corp.ru', None, 75000, '2024-02-01', 1)]
PROJECTS = [(1, 'Core Platform', 1, '2022-01-10', None), (2, 'Mobile App', 1, '2023-03-01', None), (3, 'CRM Rollout', 2, '2021-06-15', '2022-08-30'), (4, 'Brand Refresh', 3, '2023-09-05', None), (5, 'Helpdesk 2.0', 4, '2020-02-20', '2021-04-10'), (6, 'Audit Automation', 5, '2024-01-08', None)]
ASSIGNMENTS = [(1, 1, 1, 'backend', 320), (2, 2, 1, 'frontend', 280), (3, 3, 1, 'lead', 400), (4, 3, 2, 'lead', 150), (5, 1, 2, 'backend', 190), (6, 4, 3, 'analyst', 210), (7, 5, 3, 'manager', 260), (8, 6, 4, 'designer', 175), (9, 7, 4, 'copywriter', 120), (10, 8, 5, 'support', 300), (11, 9, 5, 'support', 240), (12, 10, 6, 'accountant', 130), (13, 11, 6, 'auditor', 145), (14, 2, 2, 'frontend', 95)]

SCHEMA_DOC = "Таблица `departments` — отделы компании.\n  id INTEGER PK, name TEXT, budget REAL\n\nТаблица `employees` — сотрудники.\n  id INTEGER PK, first_name TEXT, last_name TEXT, email TEXT,\n  department_id INTEGER -> departments.id (может быть NULL),\n  salary REAL, hired_at TEXT ('ГГГГ-ММ-ДД'), is_active INTEGER (1 = работает)\n\nТаблица `projects` — проекты.\n  id INTEGER PK, name TEXT, department_id INTEGER -> departments.id,\n  started_at TEXT, finished_at TEXT (NULL = проект ещё идёт)\n\nТаблица `assignments` — работы сотрудников над проектами.\n  id INTEGER PK, employee_id INTEGER -> employees.id,\n  project_id INTEGER -> projects.id, role TEXT, hours INTEGER"
MAX_ROWS = 500

# ----- логика выполнения (взята из app.py один-в-один) -----
def build_db():
    conn = sqlite3.connect(":memory:")
    conn.executescript(SCHEMA)
    conn.executemany("INSERT INTO departments VALUES (?,?,?)", DEPARTMENTS)
    conn.executemany("INSERT INTO employees VALUES (?,?,?,?,?,?,?,?)", EMPLOYEES)
    conn.executemany("INSERT INTO projects VALUES (?,?,?,?,?)", PROJECTS)
    conn.executemany("INSERT INTO assignments VALUES (?,?,?,?,?)", ASSIGNMENTS)
    conn.commit()
    return conn

def run_query(sql):
    """Выполнить SQL на свежей БД. Вернуть dict для JSON-ответа."""
    conn = build_db()
    try:
        cur = conn.execute(sql)
        rows = cur.fetchmany(MAX_ROWS + 1)
        truncated = len(rows) > MAX_ROWS
        rows = rows[:MAX_ROWS]
        columns = [d[0] for d in cur.description] if cur.description else []
        # sqlite3 может вернуть bytes — приводим к строке для JSON
        clean = [[v.decode("utf-8", "replace") if isinstance(v, bytes) else v for v in row] for row in rows]
        return {"columns": columns, "rows": clean, "truncated": truncated}
    except sqlite3.Error as exc:
        return {"error": f"{type(exc).__name__}: {exc}"}
    finally:
        conn.close()


