STATIC = {'index.html': '<!DOCTYPE html>\n<html lang="ru">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n  <title>SQL Тренажёр</title>\n  <link rel="stylesheet" href="css/style.css" />\n</head>\n<body>\n  <header class="topbar">\n    <div class="brand">🐬 SQL Тренажёр</div>\n    <div class="progress" id="progress">Прогресс: 0 / 0</div>\n    <div class="topbar-actions">\n      <button id="btn-schema" class="ghost">Схема БД</button>\n      <button id="btn-sandbox" class="ghost">Свободный режим</button>\n      <button id="btn-reset" class="ghost danger">Сбросить прогресс</button>\n    </div>\n  </header>\n\n  <main class="layout">\n    <aside class="sidebar">\n      <div class="sidebar-title">Задания по уровням</div>\n      <nav id="task-list" class="task-list"></nav>\n    </aside>\n\n    <section class="content">\n      <div class="task-head">\n        <div>\n          <div class="task-level" id="task-level"></div>\n          <h2 id="task-title"></h2>\n        </div>\n        <span id="task-status" class="badge"></span>\n      </div>\n      <p class="task-desc" id="task-desc"></p>\n\n      <div class="controls">\n        <button id="btn-run" class="primary">▶ Проверить</button>\n        <button id="btn-hint" class="ghost">💡 Подсказка</button>\n        <button id="btn-solution" class="ghost">👁 Показать решение</button>\n        <button id="btn-clear" class="ghost">Очистить</button>\n      </div>\n\n      <textarea id="editor" spellcheck="false" placeholder="Введите ваш SQL-запрос..."></textarea>\n\n      <div id="feedback" class="feedback hidden"></div>\n\n      <div class="results">\n        <div class="results-col">\n          <div class="results-caption">Результат вашего запроса</div>\n          <div id="user-result" class="result-box"></div>\n        </div>\n        <div class="results-col">\n          <div class="results-caption">Ожидаемый результат</div>\n          <div id="expected-result" class="result-box"></div>\n        </div>\n      </div>\n\n      <div class="hint-box hidden" id="hint-box"></div>\n      <div class="solution-box hidden" id="solution-box"></div>\n    </section>\n  </main>\n\n  <div id="modal" class="modal hidden">\n    <div class="modal-body">\n      <button class="modal-close" id="modal-close">✕</button>\n      <div id="modal-content"></div>\n    </div>\n  </div>\n\n  <script src="js/tasks.js"></script>\n  <script src="js/app.js"></script>\n</body>\n</html>\n', 'css/style.css': '* { box-sizing: border-box; }\nhtml, body { margin: 0; height: 100%; }\nbody {\n  background: #0f1420;\n  color: #e6ebf5;\n  font: 15px/1.5 system-ui, "Segoe UI", Roboto, sans-serif;\n}\n\n.topbar {\n  position: sticky; top: 0; z-index: 10;\n  display: flex; align-items: center; gap: 20px;\n  padding: 12px 20px; background: #171e2e;\n  border-bottom: 1px solid #2b3450;\n}\n.brand { font-weight: 700; font-size: 18px; }\n.progress { color: #8a97b3; font-variant-numeric: tabular-nums; }\n.topbar-actions { margin-left: auto; display: flex; gap: 8px; flex-wrap: wrap; }\n\n.layout {\n  display: grid; grid-template-columns: 300px 1fr;\n  gap: 16px; padding: 16px; align-items: start;\n}\n.sidebar {\n  background: #171e2e; border: 1px solid #2b3450; border-radius: 12px;\n  padding: 10px; position: sticky; top: 70px;\n  max-height: calc(100vh - 90px); overflow: auto;\n}\n.sidebar-title {\n  font-size: 12px; text-transform: uppercase; letter-spacing: 1px;\n  color: #8a97b3; padding: 6px 10px 10px;\n}\n.level-name { font-size: 12px; color: #8a97b3; padding: 10px 10px 4px; font-weight: 600; }\n.task-item {\n  display: flex; align-items: center; gap: 8px; width: 100%;\n  text-align: left; background: transparent; border: 0; color: #e6ebf5;\n  padding: 7px 10px; border-radius: 8px; cursor: pointer; font: inherit; font-size: 14px;\n}\n.task-item:hover { background: #1e2740; }\n.task-item.active { background: #4f8cff; color: #fff; }\n.task-item .mark {\n  width: 18px; height: 18px; flex: 0 0 18px; border-radius: 50%;\n  border: 2px solid #2b3450; display: inline-flex;\n  align-items: center; justify-content: center; font-size: 11px;\n}\n.task-item.solved .mark { background: #38d39f; border-color: #38d39f; color: #04120d; }\n\n.content {\n  background: #171e2e; border: 1px solid #2b3450;\n  border-radius: 12px; padding: 20px; min-width: 0;\n}\n.task-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; }\n.task-head h2 { margin: 4px 0 0; font-size: 22px; }\n.task-level { color: #4f8cff; font-size: 13px; font-weight: 600; }\n.task-desc { margin: 10px 0 16px; }\n.task-desc code {\n  font-family: "SF Mono", Consolas, monospace;\n  background: #1e2740; padding: 1px 5px; border-radius: 5px; font-size: 13px;\n}\n\n.badge {\n  padding: 5px 12px; border-radius: 999px; font-size: 12px; font-weight: 600;\n  background: #1e2740; color: #8a97b3; white-space: nowrap;\n}\n.badge.ok { background: rgba(56,211,159,.15); color: #38d39f; }\n\n.controls { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 12px; }\nbutton {\n  font: inherit; border-radius: 8px; border: 1px solid #2b3450;\n  background: #1e2740; color: #e6ebf5; padding: 8px 14px; cursor: pointer;\n  transition: .15s;\n}\nbutton:hover { border-color: #4f8cff; }\nbutton:disabled { opacity: .5; cursor: default; }\nbutton.primary { background: #4f8cff; border-color: #4f8cff; color: #fff; font-weight: 600; }\nbutton.primary:hover { background: #3a78ee; }\nbutton.danger:hover { border-color: #ff6b6b; color: #ff6b6b; }\n\n#editor {\n  width: 100%; min-height: 140px; resize: vertical;\n  background: #0b1120; color: #d5e0f5; border: 1px solid #2b3450;\n  border-radius: 10px; padding: 14px; outline: none;\n  font: 14px/1.6 "SF Mono", Consolas, monospace;\n}\n#editor:focus { border-color: #4f8cff; }\n\n.feedback {\n  margin-top: 14px; padding: 12px 16px; border-radius: 10px;\n  border: 1px solid #2b3450; background: #1e2740;\n}\n.feedback.ok { border-color: #38d39f; background: rgba(56,211,159,.1); }\n.feedback.no { border-color: #ff6b6b; background: rgba(255,107,107,.08); }\n.feedback .err { font-family: Consolas, monospace; font-size: 13px; color: #ffcc66; }\n\n.results { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-top: 16px; }\n.results-caption {\n  font-size: 12px; color: #8a97b3; text-transform: uppercase;\n  letter-spacing: 1px; margin-bottom: 6px;\n}\n.result-box {\n  background: #0b1120; border: 1px solid #2b3450; border-radius: 10px;\n  overflow: auto; max-height: 320px;\n  font: 13px/1.5 Consolas, monospace;\n}\ntable { border-collapse: collapse; width: 100%; }\nth, td {\n  padding: 6px 10px; text-align: left;\n  border-bottom: 1px solid #2b3450; white-space: nowrap;\n}\nth { color: #4f8cff; position: sticky; top: 0; background: #101a2e; }\ntr:last-child td { border-bottom: 0; }\n.empty { padding: 14px; color: #8a97b3; }\n\n.hint-box, .solution-box {\n  margin-top: 14px; padding: 12px 16px; border-radius: 10px;\n  border: 1px dashed #ffcc66; color: #ffcc66;\n}\n.solution-box { border-color: #38d39f; color: #38d39f; }\n.solution-box pre { margin: 8px 0 0; color: #e6ebf5; white-space: pre-wrap; }\n.hint-box, .solution-box pre { font-family: Consolas, monospace; font-size: 13px; }\n\n/* Utility-класс скрытия: должен перебивать любой компонентный display\n   (например .modal { display: flex }), независимо от порядка объявления. */\n.hidden { display: none !important; }\n\n.modal {\n  position: fixed; inset: 0; background: rgba(4,8,18,.7);\n  display: flex; align-items: center; justify-content: center;\n  padding: 20px; z-index: 50;\n}\n.modal-body {\n  background: #171e2e; border: 1px solid #2b3450; border-radius: 14px;\n  padding: 24px; max-width: 900px; width: 100%;\n  max-height: 85vh; overflow: auto; position: relative;\n}\n.modal-close { position: absolute; top: 12px; right: 12px; }\n.modal-body h3 { margin-top: 0; }\n.modal-body pre {\n  background: #0b1120; border: 1px solid #2b3450; border-radius: 8px;\n  padding: 14px; font: 13px/1.6 Consolas, monospace; overflow: auto;\n}\n.modal-body code {\n  font-family: Consolas, monospace; background: #1e2740;\n  padding: 1px 5px; border-radius: 5px;\n}\n\n@media (max-width: 900px) {\n  .layout { grid-template-columns: 1fr; }\n  .sidebar { position: static; max-height: none; }\n  .results { grid-template-columns: 1fr; }\n}\n', 'js/app.js': '// Фронтенд SQL-тренажёра. Задачи берутся из window.DB_TASKS (js/tasks.js),\n// выполнение SQL делегируется серверу (POST /api/execute).\n\nconst TASKS = window.DB_TASKS;\nconst LEVEL_NAMES = {\n  1: "1. Основы SELECT",\n  2: "2. Фильтрация WHERE",\n  3: "3. Сортировка и лимиты",\n  4: "4. Агрегаты и GROUP BY",\n  5: "5. JOIN нескольких таблиц",\n  6: "6. Подзапросы",\n  7: "7. CASE и условия",\n};\n\nconst STORE_DONE = "sqltr.done";\nconst STORE_DRAFTS = "sqltr.drafts";\n\nconst $ = (id) => document.getElementById(id);\n\nlet currentTask = null;\nlet sandboxMode = false;\n\n// ---------- storage ----------\nconst loadSet = (key) => {\n  try {\n    return new Set(JSON.parse(localStorage.getItem(key) || "[]"));\n  } catch {\n    return new Set();\n  }\n};\nconst saveSet = (key, set) =>\n  localStorage.setItem(key, JSON.stringify([...set]));\nconst loadDrafts = () => {\n  try {\n    return JSON.parse(localStorage.getItem(STORE_DRAFTS) || "{}");\n  } catch {\n    return {};\n  }\n};\n\nlet solved = loadSet(STORE_DONE);\n\n// ---------- sql execution ----------\nasync function executeSQL(sql) {\n  const res = await fetch("/api/execute", {\n    method: "POST",\n    headers: { "Content-Type": "application/json" },\n    body: JSON.stringify({ sql }),\n  });\n  return res.json();\n}\n\n// ---------- comparison ----------\nfunction normalizeCell(v) {\n  if (v === null || v === undefined) return "NULL";\n  if (typeof v === "number") {\n    // 150000 и 150000.0 считаются равными; дробные округляем от погрешности\n    return Math.abs(v - Math.round(v)) < 1e-9\n      ? String(Math.round(v))\n      : (Math.round(v * 1e6) / 1e6).toString();\n  }\n  return String(v);\n}\n\nfunction rowKey(row) {\n  return row.map(normalizeCell).join("\x01");\n}\n\nfunction resultsMatch(a, b, ordered) {\n  if (!a || !b) return false;\n  const ra = a.rows || [];\n  const rb = b.rows || [];\n  if (ra.length !== rb.length) return false;\n  if (ordered) {\n    return ra.every((row, i) => rowKey(row) === rowKey(rb[i]));\n  }\n  // без учёта порядка: мультимножество строк\n  const mb = {};\n  rb.forEach((r) => (mb[rowKey(r)] = (mb[rowKey(r)] || 0) + 1));\n  for (const row of ra) {\n    const k = rowKey(row);\n    if (!mb[k]) return false;\n    mb[k] -= 1;\n  }\n  return true;\n}\n\n// ---------- rendering ----------\nfunction renderTable(result) {\n  if (!result) return \'<div class="empty">—</div>\';\n  if (result.error)\n    return `<div class="empty" style="color:var(--danger)">${escapeHtml(\n      result.error\n    )}</div>`;\n  if (!result.columns || result.columns.length === 0)\n    return \'<div class="empty">Запрос выполнен (строк нет, например DDL/DML).</div>\';\n  if (result.rows.length === 0)\n    return \'<div class="empty">0 строк</div>\';\n  const head = result.columns\n    .map((c) => `<th>${escapeHtml(String(c))}</th>`)\n    .join("");\n  const body = result.rows\n    .map(\n      (r) =>\n        `<tr>${r\n          .map(\n            (v) =>\n              `<td>${\n                v === null\n                  ? \'<span style="color:var(--muted)">NULL</span>\'\n                  : escapeHtml(String(v))\n              }</td>`\n          )\n          .join("")}</tr>`\n    )\n    .join("");\n  const note = result.truncated\n    ? \'<div class="empty">Показаны первые 500 строк</div>\'\n    : "";\n  return `<table><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table>${note}`;\n}\n\nfunction escapeHtml(s) {\n  return s\n    .replace(/&/g, "&amp;")\n    .replace(/</g, "&lt;")\n    .replace(/>/g, "&gt;")\n    .replace(/"/g, "&quot;");\n}\n\nfunction renderSidebar() {\n  const byLevel = {};\n  TASKS.forEach((t) => {\n    (byLevel[t.level] = byLevel[t.level] || []).push(t);\n  });\n  const html = Object.keys(byLevel)\n    .sort((a, b) => a - b)\n    .map((lvl) => {\n      const items = byLevel[lvl]\n        .map((t) => {\n          const ok = solved.has(t.id);\n          const active = !sandboxMode && currentTask && currentTask.id === t.id;\n          return `<button class="task-item ${ok ? "solved" : ""} ${\n            active ? "active" : ""\n          }" data-id="${t.id}">\n            <span class="mark">${ok ? "✓" : ""}</span>\n            <span>${escapeHtml(t.title)}</span>\n          </button>`;\n        })\n        .join("");\n      return `<div class="level-group">\n          <div class="level-name">${LEVEL_NAMES[lvl] || "Уровень " + lvl}</div>\n          ${items}\n        </div>`;\n    })\n    .join("");\n  $("task-list").innerHTML = html;\n  $("task-list")\n    .querySelectorAll(".task-item")\n    .forEach((el) =>\n      el.addEventListener("click", () => selectTask(el.dataset.id))\n    );\n}\n\nfunction updateProgress() {\n  $("progress").textContent = `Прогресс: ${solved.size} / ${TASKS.length}`;\n}\n\nfunction formatInline(text) {\n  return escapeHtml(text).replace(\n    /`([^`]+)`/g,\n    "<code>$1</code>"\n  );\n}\n\nfunction selectTask(id) {\n  const task = TASKS.find((t) => t.id === id);\n  if (!task) return;\n  sandboxMode = false;\n  currentTask = task;\n  $("task-level").textContent = LEVEL_NAMES[task.level] || "Уровень " + task.level;\n  $("task-title").textContent = task.title;\n  $("task-desc").innerHTML = formatInline(task.description);\n  $("hint-box").classList.add("hidden");\n  $("solution-box").classList.add("hidden");\n  $("feedback").classList.add("hidden");\n  $("user-result").innerHTML = "";\n  $("expected-result").innerHTML = "";\n  $("editor").value = loadDrafts()[id] || "";\n  const st = $("task-status");\n  if (solved.has(id)) {\n    st.textContent = "Решено ✓";\n    st.className = "badge ok";\n  } else {\n    st.textContent = "Не решено";\n    st.className = "badge";\n  }\n  renderSidebar();\n}\n\nfunction enableSandbox(sqlDraft) {\n  sandboxMode = true;\n  currentTask = null;\n  $("task-level").textContent = "Свободный режим";\n  $("task-title").textContent = "Песочница";\n  $("task-desc").innerHTML =\n    "Выполните любой SQL-запрос к учебной базе — результат появится справа. Здесь нет проверки и подсказки.";\n  $("editor").value = sqlDraft || "SELECT * FROM departments;";\n  $("task-status").textContent = "Песочница";\n  $("task-status").className = "badge";\n  $("hint-box").classList.add("hidden");\n  $("solution-box").classList.add("hidden");\n  $("feedback").classList.add("hidden");\n  $("expected-result").innerHTML = "";\n  $("btn-solution").classList.add("hidden");\n  $("btn-hint").classList.add("hidden");\n  renderSidebar();\n}\n\n// ---------- check ----------\nasync function run() {\n  const sql = $("editor").value.trim();\n  const fb = $("feedback");\n  if (!sql) {\n    fb.className = "feedback no";\n    fb.innerHTML = "Введите SQL-запрос.";\n    return;\n  }\n  if (!sandboxMode) {\n    const drafts = loadDrafts();\n    drafts[currentTask.id] = $("editor").value;\n    localStorage.setItem(STORE_DRAFTS, JSON.stringify(drafts));\n  }\n\n  $("btn-run").disabled = true;\n  try {\n    const userResult = await executeSQL(sql);\n    $("user-result").innerHTML = renderTable(userResult);\n\n    if (sandboxMode) {\n      fb.className = userResult.error ? "feedback no" : "feedback ok";\n      fb.innerHTML = userResult.error\n        ? "Ошибка в запросе."\n        : "Запрос выполнен.";\n      return;\n    }\n\n    const expected = await executeSQL(currentTask.solution);\n    $("expected-result").innerHTML = renderTable(expected);\n\n    const ok =\n      !userResult.error &&\n      !expected.error &&\n      resultsMatch(userResult, expected, currentTask.ordered !== false);\n\n    if (ok) {\n      if (!solved.has(currentTask.id)) {\n        solved.add(currentTask.id);\n        saveSet(STORE_DONE, solved);\n        updateProgress();\n        renderSidebar();\n        const st = $("task-status");\n        st.textContent = "Решено ✓";\n        st.className = "badge ok";\n      }\n      fb.className = "feedback ok";\n      fb.innerHTML = "✅ Верно! Результат совпадает с ожидаемым.";\n    } else if (userResult.error) {\n      fb.className = "feedback no";\n      fb.innerHTML =\n        "❌ Запрос завершился с ошибкой:<br><span class=\'err\'>" +\n        escapeHtml(userResult.error) +\n        "</span>";\n    } else {\n      fb.className = "feedback no";\n      fb.innerHTML =\n        "❌ Результат не совпадает с ожидаемым. Сравните таблицы ниже и подумайте, что изменить.";\n    }\n  } catch (e) {\n    fb.className = "feedback no";\n    fb.innerHTML = "Ошибка соединения с сервером: " + escapeHtml(String(e));\n  } finally {\n    $("btn-run").disabled = false;\n  }\n}\n\n// ---------- modal ----------\nfunction openModal(html) {\n  $("modal-content").innerHTML = html;\n  $("modal").classList.remove("hidden");\n}\n\n// ---------- wire up ----------\nasync function showSchema() {\n  const res = await fetch("/api/schema");\n  const data = await res.json();\n  openModal(`<h3>Схема учебной базы данных</h3><pre>${escapeHtml(\n    data.schema\n  )}</pre><p style="color:var(--muted)">Пример запроса: <code>SELECT * FROM employees LIMIT 5;</code></p>`);\n}\n\n$("btn-run").addEventListener("click", run);\n$("editor").addEventListener("keydown", (e) => {\n  if ((e.ctrlKey || e.metaKey) && e.key === "Enter") {\n    e.preventDefault();\n    run();\n  }\n});\n$("btn-hint").addEventListener("click", () => {\n  if (!currentTask) return;\n  const box = $("hint-box");\n  box.textContent = "💡 " + currentTask.hint;\n  box.classList.remove("hidden");\n});\n$("btn-solution").addEventListener("click", () => {\n  if (!currentTask) return;\n  const box = $("solution-box");\n  box.innerHTML =\n    "👁 Пример решения (сравните со своим):<pre>" +\n    escapeHtml(currentTask.solution) +\n    "</pre>";\n  box.classList.remove("hidden");\n});\n$("btn-clear").addEventListener("click", () => {\n  $("editor").value = "";\n});\n$("btn-schema").addEventListener("click", showSchema);\n$("btn-sandbox").addEventListener("click", () => enableSandbox());\n$("btn-reset").addEventListener("click", () => {\n  if (!confirm("Сбросить прогресс и все черновики?")) return;\n  localStorage.removeItem(STORE_DONE);\n  localStorage.removeItem(STORE_DRAFTS);\n  solved = new Set();\n  updateProgress();\n  renderSidebar();\n  if (currentTask) selectTask(currentTask.id);\n});\n$("modal-close").addEventListener("click", () =>\n  $("modal").classList.add("hidden")\n);\n$("modal").addEventListener("click", (e) => {\n  if (e.target === $("modal")) $("modal").classList.add("hidden");\n});\n\n// ---------- init ----------\n$("btn-solution").classList.remove("hidden");\n$("btn-hint").classList.remove("hidden");\nupdateProgress();\nrenderSidebar();\nselectTask(TASKS[0].id);\n', 'js/tasks.js': '// Задания тренажёра.\n// Каждое задание: id, level, title, description, hint, solution.\n// Ожидаемый результат вычисляется приложением: solution запускается на свежей БД,\n// а ответ пользователя сравнивается с ним. Если ordered:false, строки сравниваются\n// без учёта порядка.\n\nwindow.DB_TASKS = [\n  {\n    id: \'l1-01\', level: 1, title: \'Первый SELECT\',\n    description: \'Выведите все колонки и все строки таблицы `employees`.\',\n    hint: \'SELECT * FROM employees;\',\n    solution: \'SELECT * FROM employees;\',\n    ordered: false,\n  },\n  {\n    id: \'l1-02\', level: 1, title: \'Только имена\',\n    description: \'Выведите только `first_name` и `last_name` всех сотрудников.\',\n    hint: \'Перечислите нужные колонки через запятую вместо *.\',\n    solution: \'SELECT first_name, last_name FROM employees;\',\n    ordered: false,\n  },\n  {\n    id: \'l1-03\', level: 1, title: \'Уникальные отделы\',\n    description: \'Выведите список `department_id` сотрудников без дубликатов.\',\n    hint: \'Используйте DISTINCT.\',\n    solution: \'SELECT DISTINCT department_id FROM employees;\',\n    ordered: false,\n  },\n  {\n    id: \'l1-04\', level: 1, title: \'Переименование колонки\',\n    description: \'Выведите `email` сотрудников, назвав колонку результатом `login`.\',\n    hint: \'SELECT email AS login FROM ...\',\n    solution: \'SELECT email AS login FROM employees;\',\n    ordered: false,\n  },\n  {\n    id: \'l1-05\', level: 1, title: \'Пара колонок с расчётом\',\n    description: \'Выведите `first_name` и месячную ставку `salary / 12` под именем `per_month`.\',\n    hint: \'Арифметику можно писать прямо в списке колонок.\',\n    solution: \'SELECT first_name, salary / 12 AS per_month FROM employees;\',\n    ordered: false,\n  },\n\n  {\n    id: \'l2-01\', level: 2, title: \'Фильтр по зарплате\',\n    description: \'Найдите сотрудников с зарплатой больше 150000. Выведите `first_name`, `salary`.\',\n    hint: \'WHERE salary > 150000\',\n    solution: \'SELECT first_name, salary FROM employees WHERE salary > 150000;\',\n    ordered: false,\n  },\n  {\n    id: \'l2-02\', level: 2, title: \'Два условия\',\n    description: \'Активные сотрудники (`is_active = 1`) отдела 1. Выведите все колонки.\',\n    hint: \'Объедините условия через AND.\',\n    solution: \'SELECT * FROM employees WHERE is_active = 1 AND department_id = 1;\',\n    ordered: false,\n  },\n  {\n    id: \'l2-03\', level: 2, title: \'Список значений IN\',\n    description: \'Сотрудники из отделов 2 и 4. Выведите `first_name`, `department_id`.\',\n    hint: \'WHERE department_id IN (2, 4)\',\n    solution: \'SELECT first_name, department_id FROM employees WHERE department_id IN (2, 4);\',\n    ordered: false,\n  },\n  {\n    id: \'l2-04\', level: 2, title: \'Диапазон BETWEEN\',\n    description: \'Сотрудники, принятые с 2019-01-01 по 2021-12-31 включительно. Выведите `first_name`, `hired_at`.\',\n    hint: \'WHERE hired_at BETWEEN ... AND ...\',\n    solution: "SELECT first_name, hired_at FROM employees WHERE hired_at BETWEEN \'2019-01-01\' AND \'2021-12-31\';",\n    ordered: false,\n  },\n  {\n    id: \'l2-05\', level: 2, title: \'Поиск по шаблону LIKE\',\n    description: \'Сотрудники, у которых `last_name` начинается на "S". Выведите `first_name`, `last_name`.\',\n    hint: "WHERE last_name LIKE \'S%\'",\n    solution: "SELECT first_name, last_name FROM employees WHERE last_name LIKE \'S%\';",\n    ordered: false,\n  },\n  {\n    id: \'l2-06\', level: 2, title: \'Отсутствие отдела\',\n    description: \'Сотрудники без отдела (`department_id IS NULL`). Выведите `first_name`, `last_name`.\',\n    hint: \'С NULL не сравнивают через =, используют IS NULL.\',\n    solution: \'SELECT first_name, last_name FROM employees WHERE department_id IS NULL;\',\n    ordered: false,\n  },\n  {\n    id: \'l2-07\', level: 2, title: \'NOT и отрицание\',\n    description: \'Все сотрудники, кроме уволенных (`is_active != 1`). Выведите `first_name`, `is_active`.\',\n    hint: \'Можно использовать is_active = 1 либо NOT is_active = 0.\',\n    solution: \'SELECT first_name, is_active FROM employees WHERE is_active = 1;\',\n    ordered: false,\n  },\n\n  {\n    id: \'l3-01\', level: 3, title: \'Сортировка\',\n    description: \'Все сотрудники, отсортированные по зарплате от большей к меньшей. Выведите `first_name`, `salary`.\',\n    hint: \'ORDER BY salary DESC\',\n    solution: \'SELECT first_name, salary FROM employees ORDER BY salary DESC;\',\n    ordered: true,\n  },\n  {\n    id: \'l3-02\', level: 3, title: \'Топ-3 по зарплате\',\n    description: \'Три самых дорогих сотрудника: `first_name`, `salary` по убыванию.\',\n    hint: \'ORDER BY ... DESC LIMIT 3\',\n    solution: \'SELECT first_name, salary FROM employees ORDER BY salary DESC LIMIT 3;\',\n    ordered: true,\n  },\n  {\n    id: \'l3-03\', level: 3, title: \'Пропустить и взять\',\n    description: \'Список сотрудников по алфавиту (`first_name`) со 2-го по 4-го включительно. Выведите `first_name`.\',\n    hint: \'ORDER BY first_name LIMIT 3 OFFSET 1\',\n    solution: \'SELECT first_name FROM employees ORDER BY first_name LIMIT 3 OFFSET 1;\',\n    ordered: true,\n  },\n  {\n    id: \'l3-04\', level: 3, title: \'Двойная сортировка\',\n    description: \'Сотрудники по отделу по возрастанию, внутри отдела — по зарплате по убыванию. Выведите `department_id`, `first_name`, `salary`.\',\n    hint: \'ORDER BY department_id ASC, salary DESC\',\n    solution: \'SELECT department_id, first_name, salary FROM employees ORDER BY department_id ASC, salary DESC;\',\n    ordered: true,\n  },\n\n  {\n    id: \'l4-01\', level: 4, title: \'Сколько сотрудников\',\n    description: \'Выведите общее число сотрудников в одной колонке `cnt`.\',\n    hint: \'SELECT COUNT(*) FROM employees\',\n    solution: \'SELECT COUNT(*) AS cnt FROM employees;\',\n    ordered: true,\n  },\n  {\n    id: \'l4-02\', level: 4, title: \'Средняя зарплата\',\n    description: \'Средняя зарплата по компании в колонке `avg_salary`.\',\n    hint: \'AVG(salary)\',\n    solution: \'SELECT AVG(salary) AS avg_salary FROM employees;\',\n    ordered: true,\n  },\n  {\n    id: \'l4-03\', level: 4, title: \'Сумма и максимум\',\n    description: \'Суммарный фонд (`total`) и максимальная зарплата (`max_salary`) активных сотрудников.\',\n    hint: \'SUM(salary), MAX(salary) с WHERE по is_active.\',\n    solution: \'SELECT SUM(salary) AS total, MAX(salary) AS max_salary FROM employees WHERE is_active = 1;\',\n    ordered: true,\n  },\n  {\n    id: \'l4-04\', level: 4, title: \'Группировка по отделам\',\n    description: \'Для каждого отдела: `department_id` и число сотрудников в колонке `cnt`. Сортируйте по `department_id`.\',\n    hint: \'GROUP BY department_id\',\n    solution: \'SELECT department_id, COUNT(*) AS cnt FROM employees GROUP BY department_id ORDER BY department_id;\',\n    ordered: true,\n  },\n  {\n    id: \'l4-05\', level: 4, title: \'Фильтр группы HAVING\',\n    description: \'Отделы, где больше одного сотрудника: `department_id` и `cnt`, сортировка по `department_id`.\',\n    hint: \'HAVING COUNT(*) > 1 — фильтрация уже после GROUP BY.\',\n    solution: \'SELECT department_id, COUNT(*) AS cnt FROM employees GROUP BY department_id HAVING COUNT(*) > 1 ORDER BY department_id;\',\n    ordered: true,\n  },\n  {\n    id: \'l4-06\', level: 4, title: \'Средняя зарплата по отделам\',\n    description: \'Для каждого отдела средняя зарплата `avg_salary`, только отделы со средней зарплатой больше 100000. Сортировка по `department_id`.\',\n    hint: \'AVG + GROUP BY + HAVING AVG(salary) > 100000\',\n    solution: \'SELECT department_id, AVG(salary) AS avg_salary FROM employees GROUP BY department_id HAVING AVG(salary) > 100000 ORDER BY department_id;\',\n    ordered: true,\n  },\n  {\n    id: \'l4-07\', level: 4, title: \'Сумма часов по проектам\',\n    description: \'Для каждого проекта суммарные часы `total_hours` из `assignments`. Выведите `project_id`, `total_hours`, сортировка по `project_id`.\',\n    hint: \'GROUP BY project_id\',\n    solution: \'SELECT project_id, SUM(hours) AS total_hours FROM assignments GROUP BY project_id ORDER BY project_id;\',\n    ordered: true,\n  },\n\n  {\n    id: \'l5-01\', level: 5, title: \'JOIN: имена отделов\',\n    description: \'Список сотрудников с названием отдела: `first_name`, `departments.name`. Сортировка по `first_name`.\',\n    hint: \'INNER JOIN departments ON employees.department_id = departments.id\',\n    solution: \'SELECT e.first_name, d.name FROM employees e JOIN departments d ON e.department_id = d.id ORDER BY e.first_name;\',\n    ordered: true,\n  },\n  {\n    id: \'l5-02\', level: 5, title: \'LEFT JOIN без отдела\',\n    description: \'Все сотрудники с названием отдела; у тех, у кого отдела нет, должно быть NULL. Выведите `first_name`, `d.name` как `dept`. Сортировка по `first_name`.\',\n    hint: \'LEFT JOIN сохраняет строки левой таблицы.\',\n    solution: \'SELECT e.first_name, d.name AS dept FROM employees e LEFT JOIN departments d ON e.department_id = d.id ORDER BY e.first_name;\',\n    ordered: true,\n  },\n  {\n    id: \'l5-03\', level: 5, title: \'Три таблицы\',\n    description: \'Кто и над каким проектом работает: `employees.first_name`, `projects.name`, `assignments.role`. Сортировка по имени, затем по названию проекта.\',\n    hint: \'employees -> assignments -> projects\',\n    solution: \'SELECT e.first_name, p.name, a.role FROM assignments a JOIN employees e ON a.employee_id = e.id JOIN projects p ON a.project_id = p.id ORDER BY e.first_name, p.name;\',\n    ordered: true,\n  },\n  {\n    id: \'l5-04\', level: 5, title: \'Бюджет и люди в отделе\',\n    description: \'Для каждого отдела: `d.name`, `d.budget` и число сотрудников `cnt`. Сортировка по названию отдела.\',\n    hint: \'departments LEFT JOIN employees, затем GROUP BY.\',\n    solution: \'SELECT d.name, d.budget, COUNT(e.id) AS cnt FROM departments d LEFT JOIN employees e ON e.department_id = d.id GROUP BY d.id, d.name, d.budget ORDER BY d.name;\',\n    ordered: true,\n  },\n  {\n    id: \'l5-05\', level: 5, title: \'Часы по названиям проектов\',\n    description: \'Суммарные часы по каждому проекту с названием: `projects.name`, сумма часов как `total_hours`. Сортировка по часам по убыванию.\',\n    hint: \'assignments JOIN projects + SUM(hours).\',\n    solution: \'SELECT p.name, SUM(a.hours) AS total_hours FROM assignments a JOIN projects p ON a.project_id = p.id GROUP BY p.id, p.name ORDER BY total_hours DESC;\',\n    ordered: true,\n  },\n\n  {\n    id: \'l6-01\', level: 6, title: \'Зарплата выше средней\',\n    description: \'Сотрудники с зарплатой выше средней по компании: `first_name`, `salary`. Сортировка по `salary` по убыванию.\',\n    hint: \'WHERE salary > (SELECT AVG(salary) FROM employees)\',\n    solution: \'SELECT first_name, salary FROM employees WHERE salary > (SELECT AVG(salary) FROM employees) ORDER BY salary DESC;\',\n    ordered: true,\n  },\n  {\n    id: \'l6-02\', level: 6, title: \'Самая дорогая зарплата в отделе\',\n    description: \'Для каждого отдела максимальная зарплата `max_salary` и ее владелец `first_name`. Сортировка по `department_id`. (Совпадения решаются через подзапрос на максимум.)\',\n    hint: \'JOIN c таблицей (SELECT department_id, MAX(salary) ... GROUP BY department_id)\',\n    solution: \'SELECT e.department_id, e.first_name, e.salary AS max_salary FROM employees e JOIN (SELECT department_id, MAX(salary) AS ms FROM employees GROUP BY department_id) m ON e.department_id = m.department_id AND e.salary = m.ms ORDER BY e.department_id;\',\n    ordered: true,\n  },\n  {\n    id: \'l6-03\', level: 6, title: \'Кто не на проекте\',\n    description: \'Сотрудники, у которых нет ни одной записи в `assignments`: `first_name`. Сортировка по имени.\',\n    hint: \'WHERE NOT IN (SELECT employee_id FROM assignments) или NOT EXISTS.\',\n    solution: \'SELECT first_name FROM employees WHERE id NOT IN (SELECT employee_id FROM assignments) ORDER BY first_name;\',\n    ordered: true,\n  },\n  {\n    id: \'l6-04\', level: 6, title: \'Отдел с максимальной средней зарплатой\',\n    description: \'Выведите `department_id` и среднюю зарплату `avg_salary` отдела с максимальной средней зарплатой.\',\n    hint: \'Сгруппируйте, отсортируйте по среднему и возьмите LIMIT 1.\',\n    solution: \'SELECT department_id, AVG(salary) AS avg_salary FROM employees GROUP BY department_id ORDER BY avg_salary DESC LIMIT 1;\',\n    ordered: true,\n  },\n\n  {\n    id: \'l7-01\', level: 7, title: \'CASE: категория зарплаты\',\n    description: \'Выведите `first_name` и текстовую метку `band`: "high" если зарплата > 150000, "mid" если > 100000, иначе "low". Сортировка по имени.\',\n    hint: \'CASE WHEN salary > 150000 THEN ... END\',\n    solution: "SELECT first_name, CASE WHEN salary > 150000 THEN \'high\' WHEN salary > 100000 THEN \'mid\' ELSE \'low\' END AS band FROM employees ORDER BY first_name;",\n    ordered: true,\n  },\n  {\n    id: \'l7-02\', level: 7, title: \'Условная сумма\',\n    description: \'Для каждого отдела: активные (`active_cnt`) и уволенные (`inactive_cnt`) сотрудники двумя колонками. Сортировка по `department_id` (NULL в конце допустим не будет — используйте GROUP BY department_id).\',\n    hint: \'SUM(CASE WHEN is_active = 1 THEN 1 ELSE 0 END)\',\n    solution: \'SELECT department_id, SUM(CASE WHEN is_active = 1 THEN 1 ELSE 0 END) AS active_cnt, SUM(CASE WHEN is_active = 0 THEN 1 ELSE 0 END) AS inactive_cnt FROM employees GROUP BY department_id ORDER BY department_id;\',\n    ordered: true,\n  },\n  {\n    id: \'l7-03\', level: 7, title: \'Сколько проектов у сотрудника\',\n    description: \'По всем сотрудникам: `first_name` и число проектов `projects_cnt`, включая тех, у кого 0 проектов. Сортировка: сначала больше проектов, затем по имени.\',\n    hint: \'LEFT JOIN assignments + COUNT(a.project_id)\',\n    solution: \'SELECT e.first_name, COUNT(a.project_id) AS projects_cnt FROM employees e LEFT JOIN assignments a ON a.employee_id = e.id GROUP BY e.id, e.first_name ORDER BY projects_cnt DESC, e.first_name;\',\n    ordered: true,\n  },\n  {\n    id: \'l7-04\', level: 7, title: \'Строка с датой\',\n    description: \'Выведите `first_name` и год приёма на работу как `hired_year` (первые 4 символа `hired_at`). Сортировка по году, затем по имени.\',\n    hint: \'substr(hired_at, 1, 4) или strftime(\\\'%Y\\\', hired_at)\',\n    solution: "SELECT first_name, substr(hired_at, 1, 4) AS hired_year FROM employees ORDER BY hired_year, first_name;",\n    ordered: true,\n  },\n  {\n    id: \'l7-05\', level: 7, title: \'Живые проекты с людьми\',\n    description: \'Незавершённые проекты (`finished_at IS NULL`): `projects.name` и суммарные часы `total_hours`. Только проекты, по которым есть часы. Сортировка по часам по убыванию.\',\n    hint: \'JOIN с фильтром finished_at IS NULL и GROUP BY.\',\n    solution: \'SELECT p.name, SUM(a.hours) AS total_hours FROM projects p JOIN assignments a ON a.project_id = p.id WHERE p.finished_at IS NULL GROUP BY p.id, p.name ORDER BY total_hours DESC;\',\n    ordered: true,\n  },\n];\n'}
CONTENT_TYPES = {'.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8', '.json': 'application/json; charset=utf-8', '.svg': 'image/svg+xml', '.ico': 'image/x-icon'}

DEFAULT_PORT = 12000


class Handler(BaseHTTPRequestHandler):
    def _send(self, code, body: bytes, ctype):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)

    def _json(self, obj, code=200):
        self._send(code, json.dumps(obj, ensure_ascii=False).encode("utf-8"),
                   "application/json; charset=utf-8")

    def do_GET(self):
        route = urlparse(self.path).path.lstrip("/") or "index.html"
        if route == "api/schema":
            return self._json({"schema": SCHEMA_DOC})
        if route in STATIC:
            ext = "." + route.rsplit(".", 1)[-1] if "." in route else ""
            ctype = CONTENT_TYPES.get(ext, "application/octet-stream")
            return self._send(200, STATIC[route].encode("utf-8"), ctype)
        return self._send(404, b"Not found", "text/plain")

    def do_POST(self):
        route = urlparse(self.path).path.lstrip("/")
        if route != "api/execute":
            return self._json({"error": "Unknown endpoint"}, 404)
        try:
            length = int(self.headers.get("Content-Length", 0))
            payload = json.loads(self.rfile.read(length) or b"{}")
        except (ValueError, json.JSONDecodeError):
            return self._json({"error": "Invalid JSON body"}, 400)
        sql = (payload.get("sql") or "").strip()
        if not sql:
            return self._json({"error": "Пустой запрос"})
        return self._json(run_query(sql))

    def log_message(self, *args):
        pass


def main():
    port = DEFAULT_PORT
    server = ThreadingHTTPServer(("0.0.0.0", port), Handler)
    print(f"SQL Тренажёр готов: http://localhost:{port}")
    print("Остановить: Ctrl+C")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nОстановлено.")
        server.shutdown()


if __name__ == "__main__":
    main()
